use liwe::find::{DocumentFinder, FindOptions};
use liwe::graph::Graph;
use liwe::model::config::MarkdownOptions;
use liwe::state::from_indoc;
use indoc::indoc;
use std::sync::Once;

static INIT: Once = Once::new();

fn setup() {
    INIT.call_once(|| {
        env_logger::builder().init();
    });
}

fn bare_options() -> MarkdownOptions {
    MarkdownOptions {
        bare_frontmatter: true,
        ..Default::default()
    }
}

#[test]
fn find_meta_works_with_bare_frontmatter() {
    setup();

    let graph = Graph::import(
        &from_indoc(indoc! {r#"
            [note1](1)
            _
            title: Bare Note
            depends:
              - foo
              - bar

            # Body
            "#}),
        bare_options(),
        None,
    );

    let finder = DocumentFinder::new(&graph);
    let mut options = FindOptions::default();
    options.metadata_filters = vec![("depends".to_string(), "foo".to_string())];

    let results = finder.find(&options);
    assert_eq!(results.results.len(), 1);
    assert_eq!(results.results[0].key, "1");
}

